    tokens = ["".join(t) for t in itertools.product(ALPHABET, repeat=3)]
    outs = [squeeze(t) for t in tokens]
    assert all(len(o) <= 2 and all(ch in ALPHABET for ch in o) for o in outs)
    assert len(set(outs)) == len(tokens)

